import { MakeLogicType, actions, connect, kea, key, listeners, path, props, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import api from 'lib/api'
import { resourceToApiRoute } from 'lib/utils/accessControlUtils'

import { APIScopeObject, AccessControlLevel } from '~/types'

import { accessDetailLogic } from './accessDetailLogic'
import type { ScopeType } from './types'

export interface ObjectOption {
    id: string
    name: string
}

export interface AddObjectOverrideModalLogicProps {
    projectId: string
    scopeType: ScopeType
    subjectId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface addObjectOverrideModalLogicValues {
    isOpen: boolean
    level: AccessControlLevel
    objectId: string | null
    objectOptions: ObjectOption[]
    objectOptionsLoading: boolean
    resource: string
    search: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface addObjectOverrideModalLogicActions {
    setObjectRule: (
        resource: string,
        resourceId: string,
        level: AccessControlLevel | null
    ) => {
        resource: string
        resourceId: string
        level: AccessControlLevel | null
    } // accessDetailLogic
    closeModal: () => {
        value: true
    }
    loadObjectOptions: (_: any) => any
    loadObjectOptionsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadObjectOptionsSuccess: (
        objectOptions: {
            id: string
            name: any
        }[],
        payload?: any
    ) => {
        objectOptions: {
            id: string
            name: any
        }[]
        payload?: any
    }
    openModal: () => {
        value: true
    }
    setLevel: (level: AccessControlLevel) => {
        level: AccessControlLevel
    }
    setObjectId: (objectId: string | null) => {
        objectId: string | null
    }
    setResource: (resource: string) => {
        resource: string
    }
    setSearch: (search: string) => {
        search: string
    }
    submitRule: () => {
        value: true
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface addObjectOverrideModalLogicMeta {
    key: string
}

export type addObjectOverrideModalLogicType = MakeLogicType<
    addObjectOverrideModalLogicValues,
    addObjectOverrideModalLogicActions,
    AddObjectOverrideModalLogicProps,
    addObjectOverrideModalLogicMeta
>

export const addObjectOverrideModalLogic = kea<addObjectOverrideModalLogicType>([
    path((key) => ['scenes', 'access_control', 'addObjectOverrideModalLogic', key]),
    props({} as AddObjectOverrideModalLogicProps),
    key((props) => `${props.projectId}:${props.scopeType}:${props.subjectId}`),

    connect((props: AddObjectOverrideModalLogicProps) => ({
        actions: [accessDetailLogic(props), ['setObjectRule']],
    })),

    actions({
        openModal: true,
        closeModal: true,
        setResource: (resource: string) => ({ resource }),
        setSearch: (search: string) => ({ search }),
        setObjectId: (objectId: string | null) => ({ objectId }),
        setLevel: (level: AccessControlLevel) => ({ level }),
        submitRule: true,
    }),

    reducers({
        isOpen: [false, { openModal: () => true, closeModal: () => false }],
        resource: ['dashboard', { setResource: (_, { resource }) => resource, closeModal: () => 'dashboard' }],
        search: ['', { setSearch: (_, { search }) => search, setResource: () => '', closeModal: () => '' }],
        objectId: [
            null as string | null,
            { setObjectId: (_, { objectId }) => objectId, setResource: () => null, closeModal: () => null },
        ],
        level: [
            AccessControlLevel.None as AccessControlLevel,
            { setLevel: (_, { level }) => level, closeModal: () => AccessControlLevel.None },
        ],
    }),

    loaders(({ props, values }) => ({
        objectOptions: [
            [] as ObjectOption[],
            {
                loadObjectOptions: async (_, breakpoint) => {
                    await breakpoint(300)
                    const response = await api.get<{ results: Record<string, any>[] }>(
                        `api/projects/${props.projectId}/${resourceToApiRoute(values.resource as APIScopeObject)}/?limit=20&search=${encodeURIComponent(
                            values.search
                        )}`
                    )
                    return response.results.map((item) => ({
                        id: String(item.id),
                        name: item.name || item.title || item.derived_name || item.key || String(item.id),
                    }))
                },
            },
        ],
    })),

    listeners(({ actions, values }) => ({
        openModal: () => actions.loadObjectOptions(null),
        setResource: () => actions.loadObjectOptions(null),
        setSearch: () => actions.loadObjectOptions(null),
        submitRule: () => {
            if (!values.objectId) {
                return
            }
            actions.setObjectRule(values.resource, values.objectId, values.level)
            actions.closeModal()
        },
    })),
])
